(r, big) => {
    // random level-order tree: each slot after the root is a value or a gap
    const n = big ? 6000 : r.int(0, 12), out = [];
    if (n === 0) return [[]];
    out.push(r.int(-100, 100));
    let made = 1, open = 1;
    while (made < n && open > 0) {
      for (let s = 0; s < 2 && made < n; s++) {
        if (r.bool(0.75)) { out.push(r.int(-100, 100)); made++; open++; } else out.push(null);
      }
      open--;
      if (open === 0 && made < n) { out.push(r.int(-100, 100)); made++; open++; }
    }
    return [out];
  }

