function linkRows(root: TreeNode | null): number[][] {
  if (!root) return [];
  let level: TreeNode[] = [root];
  while (level.length) {
    const below: TreeNode[] = [];
    for (let i = 0; i < level.length; i++) {
      (level[i] as any).next = i + 1 < level.length ? level[i + 1] : null;
      if (level[i].left) below.push(level[i].left!);
      if (level[i].right) below.push(level[i].right!);
    }
    level = below;
  }
  // read the answer back by following the links
  const out: number[][] = [];
  for (let head: TreeNode | null = root; head; ) {
    const row: number[] = [];
    let nextHead: TreeNode | null = null;
    for (let cur: any = head; cur; cur = cur.next) {
      row.push(cur.val);
      if (!nextHead) nextHead = cur.left || cur.right || null;
    }
    out.push(row);
    head = nextHead;
  }
  return out;
}

