class Solution:
    def linkRows(self, root: Optional[TreeNode]) -> List[List[int]]:
        if not root:
            return []
        level = [root]
        while level:
            below = []
            for i, node in enumerate(level):
                node.next = level[i + 1] if i + 1 < len(level) else None
                if node.left:
                    below.append(node.left)
                if node.right:
                    below.append(node.right)
            level = below
        # read the answer back by following the links
        out, head = [], root
        while head:
            row, nxt, cur = [], None, head
            while cur:
                row.append(cur.val)
                if nxt is None:
                    nxt = cur.left or cur.right
                cur = cur.next
            out.append(row)
            head = nxt
        return out

