function linkRows(root: TreeNode | null): number[][] {
  const out: number[][] = [];
  let head: any = root;
  while (head) {
    const dummy: any = { next: null };
    let tail: any = dummy;
    const row: number[] = [];
    for (let cur: any = head; cur; cur = cur.next) {
      row.push(cur.val);
      if (cur.left) { tail.next = cur.left; tail = cur.left; }
      if (cur.right) { tail.next = cur.right; tail = cur.right; }
    }
    tail.next = null;
    out.push(row);
    head = dummy.next;
  }
  return out;
}

